function asText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value);
  } catch (error) {
    return String(value);
  }
}

function clip(value, limit = 1200) {
  const text = asText(value).trim();
  if (!text) return '';
  return text.length > limit ? text.slice(0, limit - 3) + '...' : text;
}

function redact(value) {
  return asText(value)
    .replace(/(x-plex-token|x-api-key|api[_-]?key|apikey|token|password|senha|secret|authorization|cookie)(\s*[:=]\s*)([^\s,;\n]+)/gi, '$1$2[redigido]')
    .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [redigido]')
    .replace(/SID=[^;\s]+/gi, 'SID=[redigido]');
}

function formatDate(value) {
  if (!value) return new Date().toISOString();
  if (typeof value === 'number') return new Date(value).toISOString();
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? new Date(parsed).toISOString() : String(value);
}

const payload = $json || {};
const workflow = payload.workflow || {};
const execution = payload.execution || {};
const trigger = payload.trigger || {};
const error = execution.error || trigger.error || payload.error || {};
const cause = error.cause || {};

const workflowName = workflow.name || payload.workflowName || 'Workflow desconhecido';
const workflowId = workflow.id || payload.workflowId || 'sem id';
const executionId = execution.id || payload.executionId || 'indisponivel';
const executionMode = execution.mode || trigger.mode || payload.mode || 'desconhecido';
const executionUrl = execution.url || payload.executionUrl || '';
const retryOf = execution.retryOf || '';

const nodeFromError = error.node || payload.node || {};
const nodeName = execution.lastNodeExecuted || nodeFromError.name || nodeFromError.id || payload.lastNodeExecuted || 'desconhecido';
const nodeType = nodeFromError.type || payload.nodeType || 'nao informado';

const errorName = error.name || cause.name || payload.errorName || 'Erro';
const errorMessage = error.message || cause.message || payload.message || 'Erro sem mensagem retornada pelo n8n.';
const errorDescription = error.description || cause.description || payload.description || '';
const stack = error.stack || cause.stack || payload.stack || '';
const timestamp = formatDate(error.timestamp || trigger.timestamp || execution.startedAt || payload.timestamp);

const stackResumo = clip(redact(stack), 1200) || 'Stack trace nao disponivel.';
const descricaoResumo = errorDescription ? `\n*Descricao:* ${clip(redact(errorDescription), 700)}` : '';
const retryLine = retryOf ? `\n*Retry de:* ${retryOf}` : '';
const urlLine = executionUrl ? `\n*Abrir execucao:* ${executionUrl}` : '\n*Abrir execucao:* indisponivel. Confirme se salvar execucoes esta ativo no n8n.';

const text = clip(`🚨 *Erro no n8n - JohnFlix*\n\n*Workflow:* ${workflowName}\n*Workflow ID:* ${workflowId}\n*Execucao:* ${executionId}\n*Modo:* ${executionMode}\n*No com erro:* ${nodeName}\n*Tipo do no:* ${nodeType}\n*Erro:* ${errorName}\n*Mensagem:* ${clip(redact(errorMessage), 900)}${descricaoResumo}\n*Horario:* ${timestamp}${retryLine}${urlLine}\n\n*Stack resumida:*\n${stackResumo}`, 3900);

const adminRaw = String($env.JOHNFLIX_ADMIN_PHONES || $env.JOHNFLIX_ADMIN_PHONE || '').trim();
const admins = adminRaw
  .split(',')
  .map(v => String(v || '').replace(/\D/g, ''))
  .filter(Boolean);

if (!admins.length) {
  return [{
    json: {
      skip_send: true,
      reason: 'JOHNFLIX_ADMIN_PHONES ou JOHNFLIX_ADMIN_PHONE nao configurado',
      workflow_name: workflowName,
      node_name: nodeName,
      error_name: errorName,
      error_message: clip(redact(errorMessage), 900),
      text
    }
  }];
}

return admins.map(number => ({
  json: {
    skip_send: false,
    number,
    text,
    workflow_name: workflowName,
    workflow_id: workflowId,
    execution_id: executionId,
    execution_url: executionUrl || null,
    node_name: nodeName,
    node_type: nodeType,
    error_name: errorName,
    error_message: clip(redact(errorMessage), 900),
    timestamp
  }
}));

const items = $input.all().map(item => item.json);

return [{
  json: {
    success: true,
    alertas_processados: items.length,
    destino: items.map(item => item.number || item.to || null).filter(Boolean),
    resumo: 'Fluxo de erro executado. Verifique as respostas do node enviarAlertaErroAdmin para confirmar o envio pela Evolution API.',
    respostas: items
  }
}];

return [{
  json: {
    success: false,
    reason: $json.reason || 'Nenhum telefone de administrador configurado.',
    orientacao: 'Configure JOHNFLIX_ADMIN_PHONES com um ou mais numeros separados por virgula, ou JOHNFLIX_ADMIN_PHONE com um numero unico.',
    workflow_name: $json.workflow_name || null,
    node_name: $json.node_name || null,
    error_name: $json.error_name || null,
    error_message: $json.error_message || null
  }
}];

const item = $input.item.json || {};
function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return "'" + String(value).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}
function sqlJson(value) { return sql(JSON.stringify(value ?? null)); }
function mysqlDate(value) {
  const d = value ? new Date(value) : new Date();
  const ok = Number.isFinite(d.getTime()) ? d : new Date();
  return ok.toISOString().slice(0,19).replace('T',' ');
}
const query = `INSERT INTO johnflix_error_log (workflow_name, workflow_id, execution_id, execution_url, node_name, node_type, error_name, error_message, error_timestamp, admin_notified, payload_json) VALUES (${sql(item.workflow_name)}, ${sql(item.workflow_id)}, ${sql(item.execution_id)}, ${sql(item.execution_url)}, ${sql(item.node_name)}, ${sql(item.node_type)}, ${sql(item.error_name)}, ${sql(item.error_message)}, ${sql(mysqlDate(item.timestamp))}, ${item.skip_send ? 0 : 1}, ${sqlJson(item)});`;
return { ...item, mysql_query: query };
